import { BC } from '../lib/time';
import wikidataEvents from './wikidata-events.json' with { type: 'json' };

export type EventCategory =
  | 'politics'
  | 'war'
  | 'culture'
  | 'science'
  | 'religion'
  | 'exploration'
  | 'disaster'
  | 'economy';

export interface HistoricalEvent {
  id: string;
  /** Astronomical year (1 BC = 0). */
  year: number;
  /** Date is approximate / traditional / debated. */
  approx?: boolean;
  title: string;
  summary: string;
  lat: number;
  lon: number;
  category: EventCategory;
  /** 3 = world-changing, 2 = major, 1 = notable. */
  importance: 1 | 2 | 3;
  /** English Wikipedia article title. */
  wiki: string;
  source?: 'curated' | 'wikidata';
  sitelinks?: number;
}

export const CATEGORY_META: Record<EventCategory, { label: string; color: string }> = {
  politics: { label: 'Politics & states', color: '#c9a227' },
  war: { label: 'War & conquest', color: '#c0392b' },
  culture: { label: 'Culture & society', color: '#8e6cc0' },
  science: { label: 'Science & technology', color: '#2e86ab' },
  religion: { label: 'Religion & ideas', color: '#e07b39' },
  exploration: { label: 'Exploration & migration', color: '#2a9d8f' },
  disaster: { label: 'Disasters & disease', color: '#6c757d' },
  economy: { label: 'Economy & trade', color: '#5c8a3a' },
};

let counter = 0;
function E(
  year: number,
  title: string,
  lat: number,
  lon: number,
  category: EventCategory,
  importance: 1 | 2 | 3,
  wiki: string,
  summary: string,
  approx = false,
): HistoricalEvent {
  return { id: `ev${counter++}`, year, approx, title, summary, lat, lon, category, importance, wiki, source: 'curated' };
}

// Approximate helper: same as E but flags the date as approximate.
const A = (
  year: number,
  title: string,
  lat: number,
  lon: number,
  category: EventCategory,
  importance: 1 | 2 | 3,
  wiki: string,
  summary: string,
) => E(year, title, lat, lon, category, importance, wiki, summary, true);

